/* A logical at-issue poststate may stand for caller-visible memory only after every store is covered.
 * Pending read commands remain explicit state for capacity/composition; this does not discharge a
 * caller's later hazards or storage lifetime obligations. */
static void swdb_dx_check_exit(void) {
  for (int s = 0; s < DX_K; ++s)
    DX_CHECK(!((dx_live >> s) & 1u) || dx_kind[s] != DX_STORE_VECTOR, "swdb.dx100_memory_domain");
}

/* Live slots naming tile t in a counted role (src1, src2, dst1, dst2; not cond): what a wait on t covers. */
static unsigned int dx_counted(int t) {
  unsigned int m = 0u;
  for (int s = 0; s < DX_K; ++s)
    if (((dx_live >> s) & 1u) && (dx_dst1[s] == t || dx_dst2[s] == t || dx_src1[s] == t || dx_src2[s] == t))
      m |= dx_bit(s);
  return m;
}
/* Live slots naming tile t in any role, condition included: what a new command with destination t stalls on. */
static unsigned int dx_naming(int t) {
  unsigned int m = 0u;
  for (int s = 0; s < DX_K; ++s)
    if (((dx_live >> s) & 1u) && (dx_dst1[s] == t || dx_dst2[s] == t || dx_src1[s] == t || dx_src2[s] == t ||
                                  dx_cond[s] == t))
      m |= dx_bit(s);
  return m;
}
/* Live slots naming register r (read or written): what a CPU write of r waits for. */
static unsigned int dx_reg_users(int r) {
  unsigned int m = 0u;
  for (int s = 0; s < DX_K; ++s)
    if (((dx_live >> s) & 1u) && (((dx_regs_in[s] | dx_regs_out[s]) >> r) & 1u)) m |= dx_bit(s);
  return m;
}
/* Close a covered set under producers of input tiles, never through a range loop. */
static unsigned int dx_closure(unsigned int covered) {
  covered &= dx_live;
  for (int round = 0; round < DX_K; ++round) {
    unsigned int next = covered;
    for (int s = 0; s < DX_K; ++s)
      if (((covered >> s) & 1u) && dx_kind[s] != DX_RANGE_LOOP) next |= dx_deps[s];
    next &= dx_live;
    if (next == covered) break;
    covered = next;
  }
  return covered;
}
/* Covered commands leave the ghost state: their slots, tile and register links, and dependency bits. */
static void dx_cover(unsigned int start) {
  unsigned int m = dx_closure(start);
  if (m == 0u) return;
  dx_live &= ~m;
  for (int s = 0; s < DX_K; ++s) {
    dx_deps[s] &= ~m;
    if ((m >> s) & 1u) dx_count = dx_count - 1;
  }
  for (int t = 0; t < DX_NT; ++t) {
    if (dx_tile_writer[t] >= 0 && ((m >> dx_tile_writer[t]) & 1u)) dx_tile_writer[t] = -1;
    dx_tile_readers[t] &= ~m;
  }
  for (int r = 0; r < DX_NR; ++r) {
    if (dx_reg_writer[r] >= 0 && ((m >> dx_reg_writer[r]) & 1u)) dx_reg_writer[r] = -1;
    dx_reg_named[r] &= ~m;
  }
}

/* Dispatch one command: the stall covers, the register-overlap hazard, a free slot, the ghost links. */
static int dx_dispatch(int kind, int dst1, int dst2, int src1, int src2, int cond,
                       unsigned int regs_in, unsigned int regs_out) {
  unsigned int stall = 0u;
  if (dst1 >= 0) stall |= dx_naming(dst1);
  if (dst2 >= 0) stall |= dx_naming(dst2);
  dx_cover(stall);
  for (int s = 0; s < DX_K; ++s)
    if ((dx_live >> s) & 1u) {
      /* Indirect stores write back a whole 64-byte line (IndirectAccess.cc:898-940,1145-1158).
         Until ticket 28 models memory interference, reject concurrent memory operations involving a
         writer, even when their selected words differ. This is a model-domain check, not a refutation. */
      int incoming_memory = kind == DX_STREAM_LOAD || kind == DX_GATHER || kind == DX_STORE_VECTOR;
      int pending_memory = dx_kind[s] == DX_STREAM_LOAD || dx_kind[s] == DX_GATHER ||
                           dx_kind[s] == DX_STORE_VECTOR;
      DX_CHECK(!(incoming_memory && pending_memory &&
                 (kind == DX_STORE_VECTOR || dx_kind[s] == DX_STORE_VECTOR)), "swdb.dx100_memory_domain");
      DX_CHECK(((regs_out & (dx_regs_in[s] | dx_regs_out[s])) | (regs_in & dx_regs_out[s])) == 0u,
               DX_RULE("register_overlap"));
    }
  int slot = -1;
  for (int s = 0; s < DX_K; ++s)
    if (slot < 0 && !((dx_live >> s) & 1u)) slot = s;
  DX_CHECK(slot >= 0, "swdb.ghost_capacity");
  unsigned int deps = 0u;
  if (src1 >= 0 && dx_tile_writer[src1] >= 0) deps |= dx_bit(dx_tile_writer[src1]);
  if (src2 >= 0 && dx_tile_writer[src2] >= 0) deps |= dx_bit(dx_tile_writer[src2]);
  if (cond >= 0 && dx_tile_writer[cond] >= 0) deps |= dx_bit(dx_tile_writer[cond]);
  dx_live |= dx_bit(slot);
  dx_kind[slot] = kind; dx_dst1[slot] = dst1; dx_dst2[slot] = dst2; dx_src1[slot] = src1; dx_src2[slot] = src2;
  dx_cond[slot] = cond; dx_regs_in[slot] = regs_in; dx_regs_out[slot] = regs_out; dx_region[slot] = -1;
  dx_base[slot] = 0; dx_lo[slot] = 0; dx_hi[slot] = 0; dx_stride[slot] = 0; dx_index[slot] = -1;
  dx_deps[slot] = deps; dx_writes_memory[slot] = 0;
  if (dst1 >= 0) dx_tile_writer[dst1] = slot;
  if (dst2 >= 0) dx_tile_writer[dst2] = slot;
  if (src1 >= 0) dx_tile_readers[src1] |= dx_bit(slot);
  if (src2 >= 0) dx_tile_readers[src2] |= dx_bit(slot);
  if (cond >= 0) dx_tile_readers[cond] |= dx_bit(slot);
  dx_reg_a[slot] = -1; dx_reg_b[slot] = -1; dx_reg_c[slot] = -1;
  for (int r = 0; r < DX_NR; ++r) {
    if ((regs_out >> r) & 1u) dx_reg_writer[r] = slot;
    if (((regs_in | regs_out) >> r) & 1u) {
      dx_reg_named[r] |= dx_bit(slot);
      if (dx_reg_a[slot] < 0) dx_reg_a[slot] = r;
      else if (dx_reg_b[slot] < 0) dx_reg_b[slot] = r;
      else dx_reg_c[slot] = r;
    }
  }
  dx_count = dx_count + 1;
  return slot;
}

