int get_new_tile(void) {
  DX_CHECK(dx_next_tile < DX_NT, DX_RULE("allocation"));
  int t = dx_next_tile;
  dx_next_tile = dx_next_tile + 1;
  dx_tile_owner[t] = 0;
  return t;
}

int get_new_reg(void) {
  DX_CHECK(dx_next_reg < DX_NR, DX_RULE("allocation"));
  int r = dx_next_reg;
  dx_next_reg = dx_next_reg + 1;
  dx_reg_owner[r] = 0;
  return r;
}

void add_mem_region(void *start, void *end) {
  (void)start; (void)end;
  DX_CHECK(dx_regions < DX_NM, DX_RULE("regions"));
  dx_regions = dx_regions + 1;
}

void clear_mem_region(void) { dx_regions = 0; }

void maa_const(int value, int reg) {
  DX_CHECK(dx_reg_ok(reg), DX_RULE("operands"));
  dx_cover(dx_reg_users(reg));                      /* the device holds the write until the register is free */
  dx_reg_value[reg] = value;
}

void wait_ready(int tile) {
  DX_CHECK(dx_tile_ok(tile), DX_RULE("operands"));
  dx_cover(dx_counted(tile));
}

unsigned short get_tile_size(int tile) {
  DX_CHECK(dx_tile_ok(tile), DX_RULE("operands"));
  DX_CHECK(dx_tile_writer[tile] < 0, DX_RULE("unready_size_read"));
  return (unsigned short)dx_tile_size[tile];
}

int *get_cacheable_tile_pointer(int tile) {
  DX_CHECK(dx_tile_ok(tile), DX_RULE("operands"));
  return &dx_tile_data[tile][0];
}

void maa_stream_load(int *data, int min_reg, int max_reg, int stride_reg, int dst_tile, int cond_tile) {
  DX_CHECK(dx_reg_ok(min_reg) && dx_reg_ok(max_reg) && dx_reg_ok(stride_reg) && dx_tile_ok(dst_tile) &&
           cond_tile == -1, DX_RULE("operands"));
  long long lo = dx_reg_value[min_reg], hi = dx_reg_value[max_reg], st = dx_reg_value[stride_reg];
  DX_CHECK(st > 0 && lo <= hi, DX_RULE("stream_operands"));
  long long n = (hi == lo) ? 0 : (hi - lo - 1) / st + 1;
  if (n > DX_TS) n = DX_TS;
  int slot = dx_dispatch(DX_STREAM_LOAD, dst_tile, -1, -1, -1, -1,
                         dx_bit(min_reg) | dx_bit(max_reg) | dx_bit(stride_reg), 0u);
  for (int k = 0; k < DX_TS; ++k)
    if (k < n) dx_tile_data[dst_tile][k] = data[lo + k * st];
  dx_tile_size[dst_tile] = (int)n;
  dx_base[slot] = data; dx_lo[slot] = lo; dx_hi[slot] = hi; dx_stride[slot] = st;
}

void maa_indirect_load(int *data, int idx_tile, int dst_tile, int cond_tile) {
  DX_CHECK(dx_tile_ok(idx_tile) && dx_tile_ok(dst_tile) && dst_tile != idx_tile && cond_tile == -1,
           DX_RULE("operands"));
  int n = dx_tile_size[idx_tile];
  int slot = dx_dispatch(DX_GATHER, dst_tile, -1, idx_tile, -1, -1, 0u, 0u);
  for (int k = 0; k < DX_TS; ++k)
    if (k < n) dx_tile_data[dst_tile][k] = data[(long long)(unsigned int)dx_tile_data[idx_tile][k]];
  dx_tile_size[dst_tile] = n;
  dx_base[slot] = data; dx_index[slot] = idx_tile;
}

void maa_range_loop(int last_i_reg, int last_j_reg, int min_tile, int max_tile, int stride_reg, int dst_i_tile,
                    int dst_j_tile, int cond_tile) {
  DX_CHECK(dx_reg_ok(last_i_reg) && dx_reg_ok(last_j_reg) && dx_reg_ok(stride_reg) && last_i_reg != last_j_reg &&
           dx_tile_ok(min_tile) && dx_tile_ok(max_tile) && dx_tile_ok(dst_i_tile) && dx_tile_ok(dst_j_tile) &&
           dst_i_tile != dst_j_tile && dst_i_tile != min_tile && dst_i_tile != max_tile && dst_j_tile != min_tile &&
           dst_j_tile != max_tile && cond_tile == -1, DX_RULE("operands"));
  int li = dx_reg_value[last_i_reg], lj = dx_reg_value[last_j_reg], st = dx_reg_value[stride_reg];
  int max_i = dx_tile_size[min_tile];
  DX_CHECK(dx_tile_size[max_tile] == max_i && st > 0 && li >= 0, DX_RULE("range_operands"));
  int is[DX_TS], js[DX_TS];
  int c = 0, done = 0;
  for (int row = 0; row < DX_TS + 1; ++row) {
    if (done || li >= max_i || c >= DX_TS) { done = 1; continue; }
    if (lj == -1) lj = dx_tile_data[min_tile][li];
    unsigned int max_j = (unsigned int)dx_tile_data[max_tile][li];
    for (int e = 0; e < DX_TS; ++e)
      if ((unsigned int)lj < max_j && c < DX_TS) { is[c] = li; js[c] = lj; c = c + 1; lj = lj + st; }
    if ((unsigned int)lj >= max_j) lj = -1;
    else if (c == DX_TS) { done = 1; continue; }
    li = li + 1;
  }
  int slot = dx_dispatch(DX_RANGE_LOOP, dst_i_tile, dst_j_tile, min_tile, max_tile, -1,
                         dx_bit(last_i_reg) | dx_bit(last_j_reg) | dx_bit(stride_reg),
                         dx_bit(last_i_reg) | dx_bit(last_j_reg));
  (void)slot;
  for (int k = 0; k < DX_TS; ++k)
    if (k < c) { dx_tile_data[dst_i_tile][k] = is[k]; dx_tile_data[dst_j_tile][k] = js[k]; }
  dx_tile_size[dst_i_tile] = c; dx_tile_size[dst_j_tile] = c;
  dx_reg_value[last_i_reg] = li; dx_reg_value[last_j_reg] = lj;
}

void maa_alu_scalar(int src_tile, int src_reg, int dst_tile, int op, int cond_tile) {
  DX_CHECK(dx_tile_ok(src_tile) && dx_reg_ok(src_reg) && dx_tile_ok(dst_tile) && dst_tile != src_tile &&
           op == DX_LT_OP && cond_tile == -1, DX_RULE("operands"));
  int n = dx_tile_size[src_tile];
  int bound = dx_reg_value[src_reg];
  int slot = dx_dispatch(DX_ALU_SCALAR, dst_tile, -1, src_tile, -1, -1, dx_bit(src_reg), 0u);
  (void)slot;
  for (int k = 0; k < DX_TS; ++k)
    if (k < n) dx_tile_data[dst_tile][k] = dx_tile_data[src_tile][k] < bound ? 1 : 0;
  dx_tile_size[dst_tile] = n;
}

void maa_indirect_store_vector(int *data, int idx_tile, int src_tile, int cond_tile, int dst_tile) {
  DX_CHECK(dx_tile_ok(idx_tile) && dx_tile_ok(src_tile) && (cond_tile == -1 || dx_tile_ok(cond_tile)) &&
           (dst_tile == -1 || (dx_tile_ok(dst_tile) && dst_tile != idx_tile && dst_tile != src_tile)),
           DX_RULE("operands"));
  int n = dx_tile_size[idx_tile];
  DX_CHECK(dx_tile_size[src_tile] == n && (cond_tile == -1 || dx_tile_size[cond_tile] == n),
           DX_RULE("store_operands"));
  int slot = dx_dispatch(DX_STORE_VECTOR, dst_tile, -1, idx_tile, src_tile, cond_tile, 0u, 0u);
  for (int k = 0; k < DX_TS; ++k)
    if (k < n && (cond_tile == -1 || dx_tile_data[cond_tile][k] != 0)) {
      long long a = (long long)(unsigned int)dx_tile_data[idx_tile][k];
      int old = data[a];
      data[a] = dx_tile_data[src_tile][k];
      if (dst_tile >= 0) dx_tile_data[dst_tile][k] = old;
    }
  if (dst_tile >= 0) dx_tile_size[dst_tile] = n;
  dx_base[slot] = data; dx_index[slot] = idx_tile; dx_writes_memory[slot] = 1;
}

/* ---- ghost queries a fixture may call (not dx100-mmio calls) ---------------------------------------------- */

/* The footprint of tile t's uncovered writer: is addr one of its memory addresses? A stream: base + lo + k *
   stride for k < its count; an indirect command: base + each current element of its index tile (no copy). */
int swdb_dx_in_footprint(int tile, const int *addr) {
  DX_CHECK(dx_tile_ok(tile), DX_RULE("operands"));
  int s = dx_tile_writer[tile];
  if (s < 0 || dx_base[s] == 0) return 0;
#if defined(SWDB_CBMC)
  if (__CPROVER_POINTER_OBJECT(addr) != __CPROVER_POINTER_OBJECT(dx_base[s])) return 0;
  long long byte_position = (long long)__CPROVER_POINTER_OFFSET(addr);
  long long byte_base = (long long)__CPROVER_POINTER_OFFSET(dx_base[s]);
  if (byte_position < 0 || byte_base < 0 || byte_position % sizeof(int) != byte_base % sizeof(int)) return 0;
  unsigned long long position = (unsigned long long)byte_position / sizeof(int);
  unsigned long long base = (unsigned long long)byte_base / sizeof(int);
#else
  uintptr_t byte_position = (uintptr_t)addr, byte_base = (uintptr_t)dx_base[s];
  if (byte_position % sizeof(int) != byte_base % sizeof(int)) return 0;
  unsigned long long position = (unsigned long long)(byte_position / sizeof(int));
  unsigned long long base = (unsigned long long)(byte_base / sizeof(int));
#endif
  int negative = position < base;
  unsigned long long magnitude = negative ? base - position : position - base;
  if (dx_kind[s] == DX_STREAM_LOAD) {
    /* An interior base permits negative stream indices. Bound the unsigned magnitude before
     * conversion/negation; every stream index comes from a signed 32-bit register range. */
    if (magnitude > (negative ? 2147483648ULL : 2147483647ULL)) return 0;
    long long off = negative ? -(long long)magnitude : (long long)magnitude;
    long long n = (dx_hi[s] == dx_lo[s]) ? 0 : (dx_hi[s] - dx_lo[s] - 1) / dx_stride[s] + 1;
    if (n > DX_TS) n = DX_TS;
    return off >= dx_lo[s] && off < dx_lo[s] + n * dx_stride[s] && (off - dx_lo[s]) % dx_stride[s] == 0;
  }
  /* Indirect indices retain their unsigned 32-bit interpretation. */
  if (negative || magnitude > UINT32_MAX) return 0;
  long long off = (long long)magnitude;
  int found = 0;
  for (int k = 0; k < DX_TS; ++k)
    if (k < dx_tile_size[dx_index[s]] && off == (long long)(unsigned int)dx_tile_data[dx_index[s]][k]) found = 1;
  return found;
}


int main(void) { int a[1]={3};int b[1]={5};int *low=a,*high=b;if ((uintptr_t)low>(uintptr_t)high){low=b;high=a;}swdb_dx_init();int tile=get_new_tile();int lo=get_new_reg();int hi=get_new_reg();int step=get_new_reg();maa_const(0,lo);maa_const(1,hi);maa_const(1,step);maa_stream_load(high,lo,hi,step,tile,-1);int adjacent=(uintptr_t)(low+1)==(uintptr_t)high;int observed=swdb_dx_in_footprint(tile,low+1);printf("adjacent=%d query=%d offset=%llu live=%u count=%d\n",adjacent,observed,(unsigned long long)((uintptr_t)high-(uintptr_t)low),dx_live,dx_count);return 0;}
